{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01GpZnKW2CvTALn77aaurW1Y","type":"tool_result","content":"1\t\"\"\"Preregistered repeated-receiver visibility ablation for structural refs.\"\"\"\n2\t\n3\tfrom __future__ import annotations\n4\t\n5\timport argparse\n6\timport json\n7\tfrom pathlib import Path\n8\timport random\n9\timport secrets\n10\timport subprocess\n11\tfrom typing import Any\n12\t\n13\tfrom dogwhistle.allocation import VENDORS, benchmark, eligible_coalitions, generate_instances, score\n14\tfrom dogwhistle.gate import handoff, public_refs\n15\tfrom dogwhistle.heldout import codeword, decoded_correct, parse_receiver\n16\tfrom dogwhistle.stats import sign_flip_one_sided\n17\tfrom dogwhistle.study import (\n18\t    checkpoint, digest, ensure_published, invoke, label_commitment, load, write,\n19\t)\n20\tfrom prior_work.nns_snapshot.src.neural_node_swarm.verifier import verify_node_output\n21\t\n22\t\n23\tROOT = Path(__file__).resolve().parents[1]\n24\tFOLDER = ROOT / \"visibility\"\n25\tREGISTRATION = FOLDER / \"registration.json\"\n26\tSECRET = FOLDER / \".private\" / \"labels.json\"\n27\tARMS = (\"codeword\", \"public\", \"explicit\")\n28\tREPLICATES = 3\n29\tINSTANCES = 30\n30\tSEED = 20261026\n31\tTRIALS = INSTANCES * len(ARMS) * REPLICATES\n32\tSOURCE_FILES = (\n33\t    \"visibility/PROTOCOL.md\", \"visibility/registration.json\",\n34\t    \"dogwhistle/visibility.py\", \"tests/test_visibility.py\",\n35\t    \"dogwhistle/heldout_adapter.py\", \"dogwhistle/heldout_receiver.schema.json\",\n36\t    \"dogwhistle/codex_adapter.py\", \"dogwhistle/heldout.py\",\n37\t    \"dogwhistle/allocation.py\", \"dogwhistle/gate.py\",\n38\t    \"dogwhistle/stats.py\", \"dogwhistle/study.py\", \"pyproject.toml\",\n39\t    \"prior_work/nns_snapshot/schemas/node_output.schema.json\",\n40\t    \"prior_work/nns_snapshot/src/neural_node_swarm/verifier.py\",\n41\t)\n42\t\n43\t\n44\tdef public_decoded_pair(task: dict) -> tuple[str, str]:\n45\t    name